import argparse
import csv


def count_non_empty(path):
    counts = {}
    with open(path, newline="", encoding="utf-8-sig") as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return counts
        counts = {name: 0 for name in header}
        for row in reader:
            for i, value in enumerate(row):
                if i < len(header) and value.strip():
                    counts[header[i]] += 1
    return counts


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每列非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    args = parser.parse_args()

    counts = count_non_empty(args.csv_file)
    if not counts:
        print("文件为空")
        return
    width = max(len(name) for name in counts)
    for name, count in counts.items():
        print(f"{name:<{width}} : {count}")


if __name__ == "__main__":
    main()
